// Local-only QuickTime/JPEG packaging. Native metadata templates are generated by
// scripts/generate-live-templates.swift with AVFoundation and ImageIO.
const encoder = new TextEncoder();
const uuidPlaceholder = '11111111-1111-1111-1111-111111111111';
const decode = value => Uint8Array.from(atob(value), ch => ch.charCodeAt(0));
const view = data => new DataView(data.buffer, data.byteOffset, data.byteLength);
const u32 = (...values) => { const data = new Uint8Array(values.length * 4); values.forEach((v,i) => view(data).setUint32(i*4,v)); return data; };
export const joinBytes = (...parts) => { const result = new Uint8Array(parts.reduce((n,p)=>n+p.length,0)); let offset=0; for(const part of parts){result.set(part,offset);offset+=part.length;} return result; };
const box = (type,...parts) => { const payload=joinBytes(...parts);return joinBytes(u32(payload.length+8),encoder.encode(type),payload); };

export function readBoxes(bytes) {
  const result=[];
  for(let offset=0;offset<bytes.length;) {
    if(offset+8>bytes.length) throw new Error('实况视频结构不完整');
    const size=view(bytes).getUint32(offset);
    if(size<8 || offset+size>bytes.length) throw new Error('实况视频数据长度异常');
    result.push({type:String.fromCharCode(...bytes.slice(offset+4,offset+8)),data:bytes.slice(offset,offset+size),offset});
    offset+=size;
  }
  return result;
}
const child = (parent,name) => { const found=readBoxes(parent.slice(8)).find(b=>b.type===name);if(!found)throw new Error('缺少实况视频轨道');return found.data; };
function replaceChildren(parent,replacements,remove=[]) {
  return box(String.fromCharCode(...parent.slice(4,8)),...readBoxes(parent.slice(8))
    .filter(b=>!remove.includes(b.type)).map(b=>replacements[b.type] ?? b.data));
}
function replaceId(bytes,identifier) {
  if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(identifier)) throw new Error('实况照片标识无效');
  const result=bytes.slice(), old=encoder.encode(uuidPlaceholder), next=encoder.encode(identifier);
  let found=false;
  for(let i=0;i<=result.length-old.length;i++) {
    if(old.every((n,j)=>result[i+j]===n)){result.set(next,i);found=true;i+=old.length-1;}
  }
  if(!found)throw new Error('实况照片关联信息缺失');
  return result;
}

export function addLivePhotoMetadata(jpeg,identifier,width,height,templates) {
  if(jpeg[0]!==255||jpeg[1]!==216)throw new Error('实况封面必须是 JPG 照片');
  const app1=replaceId(decode(templates.jpegAPP1),identifier);
  view(app1).setUint32(58,width); view(app1).setUint32(70,height);
  // Input is a fresh browser canvas JPEG; no user EXIF or GPS metadata is copied.
  return joinBytes(jpeg.slice(0,2),app1,jpeg.slice(2));
}

export function createLiveMovie({samples,avcConfig,width,height,assetIdentifier,templates}) {
  if(samples.length!==90)throw new Error('实况视频需要完整的 90 帧');
  if(!avcConfig?.length || samples.some(s=>!s.data?.length) || !samples[0].key)throw new Error('实况视频编码不完整');
  if(!Number.isInteger(width)||!Number.isInteger(height)||width<2||height<2||width>4096||height>4096)throw new Error('实况视频尺寸无效');
  const ftyp=decode(templates.ftyp), metadataSample=decode(templates.metadataSample);
  const videoBytes=joinBytes(...samples.map(s=>s.data));
  const movie=replaceId(decode(templates.moov),assetIdentifier);
  const top=readBoxes(movie.slice(8));
  const tracks=top.filter(b=>b.type==='trak');
  const videoTrack=tracks[0].data, metadataTrack=tracks[1].data;
  const mdia=child(videoTrack,'mdia'), minf=child(mdia,'minf'), stbl=child(minf,'stbl');
  const originalDescription=child(stbl,'stsd');
  const avc1=originalDescription.slice(16);
  const header=avc1.slice(8,86);
  view(header).setUint16(24,width); view(header).setUint16(26,height);
  const description=box('stsd',u32(0,1),box('avc1',header,box('avcC',avcConfig)));
  const keyframes=samples.flatMap((s,i)=>s.key?[i+1]:[]);
  const sampleTable=box('stbl',description,
    box('stts',u32(0,1,90,20)), // 600 ticks/second, 30 frames/second, exactly 3 seconds.
    box('stss',u32(0,keyframes.length,...keyframes)),
    box('stsc',u32(0,1,1,90,1)),
    box('stsz',u32(0,0,90,...samples.map(s=>s.data.length))),
    box('stco',u32(0,1,ftyp.length+8)));
  const trackHeader=child(videoTrack,'tkhd');
  view(trackHeader).setUint32(trackHeader.length-8,width*65536);
  view(trackHeader).setUint32(trackHeader.length-4,height*65536);
  const newVideoTrack=replaceChildren(videoTrack,{tkhd:trackHeader,mdia:replaceChildren(mdia,{minf:replaceChildren(minf,{stbl:sampleTable})})},['tapt']);
  const metaMdia=child(metadataTrack,'mdia'), metaMinf=child(metaMdia,'minf'), metaStbl=child(metaMinf,'stbl');
  const metaHeader=child(metadataTrack,'tkhd');view(metaHeader).setUint32(28,1800);
  const edits=child(metadataTrack,'edts'),editList=child(edits,'elst');
  view(editList).setUint32(16,1780); // Last frame: 89 / 30 seconds, 20 ticks before the 3-second endpoint.
  const newMetadataTrack=replaceChildren(metadataTrack,{tkhd:metaHeader,edts:replaceChildren(edits,{elst:editList}),mdia:replaceChildren(metaMdia,{minf:replaceChildren(metaMinf,{stbl:replaceChildren(metaStbl,{stco:box('stco',u32(0,1,ftyp.length+8+videoBytes.length))})})})});
  let trackIndex=0;
  const moov=box('moov',...top.map(b=>b.type==='trak' ? (trackIndex++===0?newVideoTrack:newMetadataTrack) : b.data));
  return joinBytes(ftyp,box('mdat',videoBytes,metadataSample),moov);
}

function crc32(bytes) {
  let crc=0xffffffff;
  for(const byte of bytes){crc^=byte;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}
  return (crc^0xffffffff)>>>0;
}

export function createZip(files) {
  const local=[],central=[];let offset=0;
  for(const {name,data} of files){
    const filename=encoder.encode(name),crc=crc32(data);
    const header=new Uint8Array(30),d=view(header);
    d.setUint32(0,0x04034b50,true);d.setUint16(4,20,true);d.setUint16(6,0x800,true);
    d.setUint16(12,0x21,true);d.setUint32(14,crc,true);d.setUint32(18,data.length,true);d.setUint32(22,data.length,true);d.setUint16(26,filename.length,true);
    local.push(header,filename,data);
    const directory=new Uint8Array(46),c=view(directory);
    c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint16(14,0x21,true);
    c.setUint32(16,crc,true);c.setUint32(20,data.length,true);c.setUint32(24,data.length,true);c.setUint16(28,filename.length,true);c.setUint32(42,offset,true);
    central.push(directory,filename);offset+=header.length+filename.length+data.length;
  }
  const directory=joinBytes(...central),end=new Uint8Array(22),d=view(end);
  d.setUint32(0,0x06054b50,true);d.setUint16(8,files.length,true);d.setUint16(10,files.length,true);d.setUint32(12,directory.length,true);d.setUint32(16,offset,true);
  return joinBytes(...local,directory,end);
}
